pub fn declared_names(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    for item in items.iter() {
        let name = name_declared(names, &item.node);
        if !name.is_empty() { out.push(name); }
    }
    out
}

pub fn a_use_refused(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], here: &str, reachable: &collections::BTreeSet<String>, alone: bool, beside: &impl Fn(&str) -> bool) -> Option<String> {
    let mut named: Vec<(String, String)> = vec![];
    for item in items.iter() {
        let segments = use_segments(names, &item.node);
        if segments.is_empty() || *nikaia_std::index::get(&segments, 0) == "std" { continue; }
        let first = (*nikaia_std::index::get(&segments, 0)).to_string();
        if segments.len() > 1 {
            let written = segments.join("::");
            return Some(format!("`use {}` in {}: `use` takes a package name only, not a path into it. Write `use {}`, and `{}` where you need it.", written, here, first, written));
        }
        let called = alias_of(names, &item.node);
        if !called.is_empty() { named.push((first, called)); } else { named.push((first.to_string(), first)); }
    }
    let mut once: collections::BTreeSet<String> = collections::BTreeSet::new();
    for (_, called) in named.iter() {
        if once.contains(called) { return Some(format!("`{}` is used twice in {}. Two packages can't have the same name in one file. Write `use … as …` to give one of them another name.", called, here)); }
        once.insert(called.to_string());
    }
    for (package, _) in named.iter() {
        if reachable.contains(package) { continue; }
        if alone { return Some(format!("`use {}` in {}: a single file outside a project has no dependencies, so there's no `{}` to use.\nDependencies are declared in a project's `nikaia.toml`. Put this file in a project whose `nikaia.toml` declares it:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package)); }
        if beside(package) { return Some(format!("`use {}` in {}: the files of a package already see each other, so there's nothing to bring in. Remove the line and use the name directly.", package, here)); }
        return Some(format!("`use {}` in {}: there's no dependency called `{}`.\nAdd it to the project's `[dependencies]` under that name:\n    [dependencies]\n    {} = {{ path = \"../{}\" }}", package, here, package, package, package));
    }
    None
}

pub(crate) fn use_segments(names: &winnow_grammar::InternerContext, item: &Item) -> Vec<String> {
    let mut out: Vec<String> = vec![];
    match item {
        Item::Import { path, .. } => {
            for segment in path.iter() {
                let segment = *segment;
                out.push(names.resolve(segment).to_string());
            }
        },
        _ => { },
    }
    out
}

pub(crate) fn alias_of(names: &winnow_grammar::InternerContext, item: &Item) -> String {
    match item {
        Item::Import { alias, .. } => { let alias = *alias; a_symbols_text(names, alias) },
        _ => String::from(""),
    }
}

pub fn could_promise(contracts: &Ledger, theirs: &collections::BTreeMap<String, Ledger>, paused_by_code: &collections::BTreeMap<String, Vec<String>>) -> String {
    let mut never: Vec<String> = vec![];
    for (key, contract) in contracts.functions.iter() { if !of_a_dependency(key, theirs) && contract.public && inferred_sync(&contract.sync_claim) { never.push(format!("`{}`", key)); } }
    let mut through: Vec<String> = vec![];
    for (key, lambdas) in paused_by_code.iter() {
        let contract = match *nikaia_std::index::get(&contracts.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if of_a_dependency(key, theirs) || !contract.public || !no_sync(&contract.sync_claim) { continue; }
        let mut named: Vec<String> = vec![];
        for lambda in lambdas.iter() { if !nikaia_std::list::contains(&contract.keeps, &lambda) { named.push(lambda.to_string()); } }
        if (named.len() as i64) == lambdas.len() as i64 { through.push(format!("`{}` (`sync({})`)", key, named.join(", "))); }
    }
    let mut out: String = String::from("");
    if !never.is_empty() {
        let one = never.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", never.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} never pause{} and do{} not promise it: {}\n  help: write `sync` after the result, and callers in other packages can rely on it\n", count, functions, s, es, never.join(", ")));
    }
    if !through.is_empty() {
        let one = through.len() == 1;
        let count = if one { String::from("") } else { format!("{} ", through.len() as i64) };
        let functions = if one { "1 pub function" } else { "pub functions" };
        let s = if one { "s" } else { "" };
        let they = if one { "it is" } else { "they are" };
        let es = if one { "es" } else { "" };
        out.push_str(&format!("note: {}{} pause{} only where the lambdas {} given do, and do{} not promise it: {}\n  help: write `sync(f)` after the result, naming those lambdas, and callers in other packages can rely on it\n", count, functions, s, they, es, through.join(", ")));
    }
    out
}

pub(crate) fn of_a_dependency(key: &str, theirs: &collections::BTreeMap<String, Ledger>) -> bool {
    let parts: Vec<&str> = key.splitn(2, "::").collect::<Vec<_>>();
    parts.len() == 2 && theirs.contains_key(*nikaia_std::index::get(&parts, 0))
}

pub(crate) fn inferred_sync(claim: &Sync) -> bool { matches!(claim, Sync::Inferred) }

pub(crate) fn no_sync(claim: &Sync) -> bool { matches!(claim, Sync::No) }

pub fn pause_path(chain: &[String]) -> String {
    let mut steps: Vec<String> = vec![];
    let mut k: i64 = 0;
    while ((k + 1) as usize) < chain.len() {
        steps.push(format!("`{}` calls `{}`", *nikaia_std::index::get(&chain, (k) as usize), *nikaia_std::index::get(&chain, (k + 1) as usize)));
        k += 1;
    }
    steps.join(", which ")
}

pub fn lost_sync(contracts: &Ledger, theirs: &collections::BTreeMap<String, Ledger>, pauses: &collections::BTreeMap<String, ModulesPause>, committed: &Ledger, render: &impl Fn(&CheckFinding, i64) -> String) -> String {
    let mut out: String = String::from("");
    for (key, now) in contracts.functions.iter() {
        if of_a_dependency(key, theirs) || !now.public || now.sync_claim.is_sync() { continue; }
        let before = match *nikaia_std::index::get(&committed.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue };
        if !inferred_sync(&before.sync_claim) { continue; }
        let message = format!("`{}` could not pause before, and now it can.", key);
        let help = format!("If `{}` should not pause, move this out of it; if it may, commit `nikaia.contracts`, and this is not said again.", key);
        let pause = match *nikaia_std::index::get(&pauses, key) { Some(__nikaia_value) => __nikaia_value, None => {
            out.push_str(&lost_sync_unplaced(&message, &help));
            continue;
        } };
        let site = match match pause.site.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => {
            out.push_str(&lost_sync_unplaced(&message, &help));
            continue;
        } };
        let mut notes: Vec<String> = vec![];
        if pause.chain.len() > 1 { notes.push(format!("{}, which pauses here.", pause_path(&pause.chain))); }
        notes.push(format!("{} can pause.", site.what));
        let finding = CheckFinding { severity: CheckSeverity::Warning, span: Span { start: site.span.start, end: site.span.end }, code: String::from("NK2211"), message, notes, help: Some(help), labels: vec![] };
        out.push_str(&render(&finding, pause.unit));
    }
    out
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModulesPause {
    pub chain: Vec<String>,
    pub unit: i64,
    pub site: Option<Site>,
}

pub fn lost_sync_unplaced(message: &str, help: &str) -> String { format!("warning[NK2211]: {}\n   = note: a method call it makes, or one of the calls it leads to, can pause.\n   = help: {}\n", message, help) }

pub fn declared_once(paths: &[String], declared: &[Vec<String>]) -> Option<String> {
    let mut seen: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for at in 0..paths.len() as i64 {
        let path = (*nikaia_std::index::get(&paths, (at) as usize)).to_string();
        for name in (*nikaia_std::index::get(&declared, (at) as usize)).iter() {
            if seen.contains_key(name) {
                let first = nikaia_std::index::or(*nikaia_std::index::get(&seen, name), || "").to_string();
                if first == path { continue; }
                return Some(format!("`{}` is declared twice in this package: in {} and in {}.\nAll files of a package share their names. Rename one of the two, or keep one declaration and use it from the other file.", name, first, path));
            }
            seen.insert(name.to_string(), path.to_string());
        }
    }
    None
}

pub fn groups(packages: &[Option<String>]) -> Vec<(i64, i64)> {
    let mut out: Vec<(i64, i64)> = vec![];
    let mut at: i64 = 0;
    while ((at) as usize) < packages.len() {
        let from: i64 = at;
        while ((at) as usize) < packages.len() && *nikaia_std::index::get(&packages, (at) as usize) == *nikaia_std::index::get(&packages, nikaia_std::index::at(from)) { at += 1; }
        out.push((from, at));
    }
    out
}

pub fn as_promised(ledger: &mut Ledger, another: &impl Fn(&str) -> bool) {
    let mut unpromised: Vec<String> = vec![];
    for (key, contract) in ledger.functions.iter() { if inferred_sync(&contract.sync_claim) && another(key) { unpromised.push(key.to_string()); } }
    for key in unpromised.iter() {
        let mut entry = match *nikaia_std::index::get(&ledger.functions, key) { Some(__nikaia_value) => __nikaia_value, None => continue }.clone();
        entry.sync_claim = Sync::Unpromised;
        ledger.functions.insert(key.to_string(), entry);
    }
}

pub fn contracts_as_promised(contracts: &Ledger, theirs: &collections::BTreeMap<String, Ledger>) -> Ledger {
    let mut promised = contracts.clone();
    as_promised(&mut promised, &|key| { of_a_dependency(key, theirs) });
    promised
}

#[allow(clippy::too_many_arguments)]
pub fn dependency_ledgers(library: &mut Ledger, contracts: &mut Ledger, described: &Ledger, packages: &[Option<String>], renames: &[collections::BTreeMap<String, String>], reaches: &collections::BTreeMap<String, collections::BTreeSet<String>>, their_renames: &collections::BTreeMap<String, collections::BTreeMap<String, String>>, package_ledger: &impl Fn(i64, i64) -> Ledger) -> collections::BTreeMap<String, Ledger> {
    for (name, contract) in described.functions.iter() { if !library.functions.contains_key(name) { library.functions.insert(name.to_string(), contract.clone()); } }
    for (name, contract) in described.types.iter() { if !library.types.contains_key(name) { library.types.insert(name.to_string(), contract.clone()); } }
    let mut plain: collections::BTreeMap<String, Ledger> = collections::BTreeMap::new();
    for (from, to) in groups(packages) {
        let package = match match nikaia_std::index::get(&packages, nikaia_std::index::at(from)) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        } { Some(__nikaia_value) => __nikaia_value, None => continue };
        let module: Option<String> = Some(package.to_string());
        let own = package_ledger(from, to);
        let mut promised = own.clone();
        as_promised(&mut promised, &|key| { true });
        absorb_into(library, (module).as_deref(), nikaia_std::index::get(&renames, nikaia_std::index::at(from)), &promised);
        absorb_into(contracts, (module).as_deref(), nikaia_std::index::get(&renames, nikaia_std::index::at(from)), &own);
        plain.insert(package, own);
    }
    let none: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    let mut as_its_own: collections::BTreeMap<String, Ledger> = collections::BTreeMap::new();
    for (package, own) in plain.iter() {
        let mut seen_by_it = own.clone();
        let words = nikaia_std::index::or(match *nikaia_std::index::get(&reaches, package) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeSet::new().into());
        let renamed = nikaia_std::index::or(match *nikaia_std::index::get(&their_renames, package) {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, || collections::BTreeMap::new().into());
        for word in words.iter() {
            let ours = nikaia_std::index::or(*nikaia_std::index::get(&renamed, word), || word).to_string();
            if ours == *package { continue; }
            let theirs = match *nikaia_std::index::get(&plain, &ours) { Some(__nikaia_value) => __nikaia_value, None => continue };
            let mut promised = theirs.clone();
            as_promised(&mut promised, &|key| { true });
            let module: Option<String> = Some(word.to_string());
            absorb_into(&mut seen_by_it, (module).as_deref(), &none, &promised);
        }
        as_its_own.insert(package.to_string(), seen_by_it);
    }
    as_its_own
}

pub fn absorb_own(contracts: &mut Ledger, renames: &collections::BTreeMap<String, String>, own: &Ledger) {
    contracts.sources = own.sources.to_owned();
    let module: Option<String> = None;
    absorb_into(contracts, (module).as_deref(), renames, own);
}

pub fn shown_paths(paths: &[String], shown_as: Option<&str>) -> Vec<String> {
    (nikaia_std::range::span(0, paths.len() as i64)).map(|at| {
        if at == 0 && shown_as.is_some() {
            nikaia_std::index::or(match shown_as {
                Some(__nikaia_it) => Some(__nikaia_it.to_string()),
                None => None,
            }, || "".into())
        } else { (*nikaia_std::index::get(&paths, nikaia_std::index::at(at))).to_string() }
    }).collect::<Vec<_>>()
}

pub fn package_names(packages: &[Option<String>]) -> collections::BTreeSet<String> {
    packages.iter().filter_map(|p| {
        match p.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }
    }).collect()
}

pub fn is_single_file(units: i64) -> bool { units == 1 }

pub fn test_function(k: i64) -> String { format!("__nikaia_test_{}", k) }

pub fn test_dispatcher(cli: &str, with_use: bool, count: i64, dispatch: &str) -> String {
    let mut text: String = String::from("");
    if with_use { text.push_str("use std::cli\n"); }
    text.push_str(&format!("fn {}() throws {{\n    let which = {}::args().nth(1) ?? \"\"\n", dispatch, cli));
    for k in 0..count { text.push_str(&format!("    if which == \"{}\" {{\n        {}()\n        return\n    }}\n", k, test_function(k))); }
    text.push_str("    panic(f\"this build has no test numbered `{which}`\")\n}\n");
    text
}

pub fn modules_test_count(items: &[Spanned<Item>]) -> i64 { items.iter().filter(|&item| { matches!(item.node, Item::Test { .. }) }).count() as i64 }

pub fn modules_cli_word(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>]) -> Option<String> {
    for item in items.iter() {
        let path = use_segments(names, &item.node);
        if path.len() == 2 && *nikaia_std::index::get(&path, 0) == "std" && *nikaia_std::index::get(&path, 1) == "cli" {
            let alias = alias_of(names, &item.node);
            if !alias.is_empty() { return Some(alias); }
            return Some(String::from("cli"));
        }
    }
    None
}

pub fn modules_dispatcher_as_main(items: &mut Vec<Spanned<Item>>, names: &winnow_grammar::InternerContext, dispatch: &str, intern: &impl Fn(&str) -> winnow_grammar::Symbol) {
    let main = intern("main");
    let mut kept: Vec<Spanned<Item>> = vec![];
    for item in items.drain(..) {
        let named = match item.node {
            Item::Fn { name, .. } => a_symbols_text(names, name),
            _ => String::from(""),
        };
        if named == "main" { continue; }
        if named == dispatch {
            let node = modules_named(item.node, main);
            kept.push(Spanned { node, span: item.span, doc: item.doc, attributes: item.attributes });
        } else { kept.push(item); }
    }
    items.extend(kept);
}

pub(crate) fn modules_named(item: Item, to: winnow_grammar::Symbol) -> Item {
    match item {
        Item::Fn { name, generics, receiver, args, config, spread, ret_type, body, is_sync, sync_by, is_public, can_throw, is_extern } => Item::Fn { name: Some(to), generics, receiver, args, config, spread, ret_type, body, is_sync, sync_by, is_public, can_throw, is_extern },
        other => other,
    }
}

pub fn modules_tests_as_functions(items: &mut Vec<Spanned<Item>>, source: &str, first: i64, intern: &impl Fn(&str) -> winnow_grammar::Symbol) -> Vec<(String, i64)> {
    let mut tests: Vec<(String, i64)> = vec![];
    let mut kept: Vec<Spanned<Item>> = vec![];
    for item in items.drain(..) {
        let start = item.span.start as i64;
        match item.node {
            Item::Test { name, body } => {
                let function: Option<winnow_grammar::Symbol> = Some(intern(&test_function(first + tests.len() as i64)));
                tests.push((name, modules_line_of(source, start)));
                let node = Item::Fn { name: function, generics: vec![], receiver: None, args: vec![], config: vec![], spread: None, ret_type: None, body, is_sync: false, sync_by: vec![], is_public: false, can_throw: true, is_extern: false };
                kept.push(Spanned { node, span: item.span, doc: item.doc, attributes: item.attributes });
            },
            other => { kept.push(Spanned { node: other, span: item.span, doc: item.doc, attributes: item.attributes }); },
        }
    }
    items.extend(kept);
    tests
}

pub(crate) fn modules_line_of(source: &str, at: i64) -> i64 {
    let mut line: i64 = 1;
    let mut seen: i64 = 0;
    for b in source.bytes() {
        if seen >= at { break; }
        if (b as i64) == 10 { line += 1; }
        seen += 1;
    }
    line
}

pub fn modules_names_in(names: &winnow_grammar::InternerContext, items: &[Spanned<Item>], out: &mut collections::BTreeSet<String>) {
    let mut bodies: Vec<&Block> = vec![];
    for item in items.iter() {
        match &item.node {
            Item::Fn { body, .. } => { bodies.push(body); },
            Item::Impl { methods, .. } => {
                for method in methods.iter() {
                    match &method.node {
                        Item::Fn { body, .. } => { bodies.push(body); },
                        _ => { },
                    }
                }
            },
            _ => { },
        }
    }
    for body in bodies.iter() {
        let body = *body;
        for e in visited_in_block(body) { modules_note(names, e, out); }
    }
}

pub(crate) fn modules_note(names: &winnow_grammar::InternerContext, e: &Expr, out: &mut collections::BTreeSet<String>) {
    match e {
        Expr::Path(segments, _) => { if !segments.is_empty() { out.insert(names.resolve(*nikaia_std::index::get(&segments, nikaia_std::index::at(segments.len() as i64 - 1))).to_string()); } },
        Expr::Variable(n, _) => {
            let n = *n;
            out.insert(names.resolve(n).to_string());
        },
        Expr::MethodCall { method, .. } => {
            let method = *method;
            out.insert(names.resolve(method).to_string());
        },
        Expr::SafeMethod { method, .. } => {
            let method = *method;
            out.insert(names.resolve(method).to_string());
        },
        Expr::StructLit { name, .. } => {
            let name = *name;
            out.insert(names.resolve(name).to_string());
        },
        Expr::LitInterpolated { parts, .. } => {
            for part in parts.iter() {
                match part {
                    FPart::Hole { expr, .. } => { for inner in visited_in_expr(expr) { modules_note(names, inner, out); } },
                    _ => { },
                }
            }
        },
        _ => { },
    }
}

pub trait ModulesHost {
    fn parse_unit(&self, path: &std::path::Path, source: &str, package: Option<String>) -> Option<i64>;
    fn declared(&self, unit: i64) -> Vec<String>;
    fn use_refused(&self, unit: i64, at: &std::path::Path, reachable: &collections::BTreeSet<String>, alone: bool) -> Option<String>;
    fn foreign_crates(&self, path: &std::path::Path) -> Vec<String>;
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ModulesRefusal {
    Parse,
    Refused(String),
    Unreadable { what: String, why: String },
}

impl ModulesRefusal {
    pub(crate) fn message(&self) -> String {
        match self {
            ModulesRefusal::Parse => String::from("a file did not parse"),
            ModulesRefusal::Refused(why) => why.to_string(),
            ModulesRefusal::Unreadable { what, why } => format!("{}: {}", what, why),
        }
    }
}
impl std::fmt::Display for ModulesRefusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.message())
    }
}
impl std::error::Error for ModulesRefusal {}

#[derive(Debug, Clone, PartialEq)]
pub struct ModulesUnit {
    pub path: fs::Path,
    pub source: String,
    pub parsed: i64,
    pub package: Option<String>,
    pub renames: collections::BTreeMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModulesStanding {
    InProject,
    Alone,
}

pub(crate) const MODULES_SRC: &str = "src";

pub(crate) const MODULES_ENTRY: &str = "main.nika";

pub fn modules_qualify(package: Option<String>, name: &str) -> String {
    let package = match package { Some(__nikaia_value) => __nikaia_value, None => return name.to_string() };
    format!("{}::{}", package, name)
}

pub async fn modules_collect_with<H: ModulesHost>(entry: &std::path::Path, dependencies: &[ProjectMembersDependency], host: &H) -> Result<Vec<ModulesUnit>, nikaia_std::error::Thrown<ModulesRefusal>> {
    let mut names: collections::BTreeSet<String> = dependencies.iter().map(|d| { d.name.to_string() }).collect();
    names.extend(modules_foreign_beside(entry, host));
    let mut units = modules_package_at(entry, &None, &names, &collections::BTreeMap::new(), host).await?;
    for dependency in dependencies.iter() {
        let src = nikaia_std::fs::path::join(&(dependency.root), std::path::Path::new(&(MODULES_SRC)));
        if !modules_is_dir(&src) { return Err(nikaia_std::error::throwing(ModulesRefusal::Refused(format!("`{}` is a dependency by path, but {} doesn't exist.\nA package is a directory with a `{}/` folder in it.", dependency.name, nikaia_std::fs::path::display(&(src)), MODULES_SRC)), &"modules_collect_with")); }
        let package: Option<String> = Some(dependency.name.to_string());
        units.extend(modules_package_at(&nikaia_std::fs::path::join(&(src), std::path::Path::new(&(MODULES_ENTRY))), &package, &dependency.reachable, &dependency.renames, host).await?);
    }
    Ok(units)
}

pub(crate) async fn modules_package_at<H: ModulesHost>(entry: &std::path::Path, package: &Option<String>, reachable: &collections::BTreeSet<String>, renames: &collections::BTreeMap<String, String>, host: &H) -> Result<Vec<ModulesUnit>, nikaia_std::error::Thrown<ModulesRefusal>> {
    let base = modules_base_of(entry);
    let names = match fs::read_dir(&base, &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::throwing(ModulesRefusal::Unreadable { what: format!("cannot read {}", nikaia_std::fs::path::display(&(base))), why: format!("{}", error) }, &"modules_package_at")) },
    };
    let entry_name = nikaia_std::index::or(match nikaia_std::fs::path::file_name(&(entry)).as_ref() {
        Some(__nikaia_it) => Some(nikaia_std::fs::path::text_of(&(__nikaia_it))),
        None => None,
    }, || "".into());
    let beside: Vec<fs::Path> = names.iter().filter(|&name| {
        nikaia_std::index::or(match nikaia_std::fs::path::extension(&(name)).as_ref() {
            Some(__nikaia_it) => Some(nikaia_std::fs::path::text_of(&(__nikaia_it))),
            None => None,
        }, || "".into()) == "nika"
    }).filter(|&name| { nikaia_std::fs::path::text_of(&(name)) != entry_name }).map(|name| { nikaia_std::fs::path::join(&(base), name) }).collect::<Vec<_>>();
    let mut units: Vec<ModulesUnit> = vec![];
    if modules_is_file(entry) {
        units.push(modules_read_unit(entry, match package.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, reachable, renames, ModulesStanding::InProject, host).await?);
    }
    for path in beside.iter() {
        units.push(modules_read_unit(path, match package.as_ref() {
            Some(__nikaia_it) => Some(__nikaia_it.clone()),
            None => None,
        }, reachable, renames, ModulesStanding::InProject, host).await?);
    }
    modules_one_namespace(&units, host)?;
    Ok(units)
}

pub(crate) fn modules_base_of(entry: &std::path::Path) -> fs::Path {
    let here: fs::Path = std::path::PathBuf::from(".");
    let parent = match nikaia_std::fs::path::parent(&(entry)) { Some(__nikaia_value) => __nikaia_value, None => return here };
    if nikaia_std::fs::path::text_of(&(parent)).is_empty() { return here; }
    parent
}

pub async fn modules_collect_one<H: ModulesHost>(entry: &std::path::Path, host: &H) -> Result<Vec<ModulesUnit>, nikaia_std::error::Thrown<ModulesRefusal>> {
    Ok(vec![modules_read_unit(entry, None, &collections::BTreeSet::new(), &collections::BTreeMap::new(), ModulesStanding::Alone, host).await?])
}

pub(crate) async fn modules_read_unit<H: ModulesHost>(path: &std::path::Path, package: Option<String>, reachable: &collections::BTreeSet<String>, renames: &collections::BTreeMap<String, String>, standing: ModulesStanding, host: &H) -> Result<ModulesUnit, nikaia_std::error::Thrown<ModulesRefusal>> {
    let source = match fs::read_to_string(path, &fs::Root::Anywhere).await {
        Ok(value) => value,
        Err(error) => { return Err(nikaia_std::error::throwing(ModulesRefusal::Unreadable { what: format!("cannot read {}", nikaia_std::fs::path::display(&(path))), why: format!("{}", error) }, &"modules_read_unit")) },
    };
    let parsed = match host.parse_unit(path, &source, match package.as_ref() {
        Some(__nikaia_it) => Some(__nikaia_it.clone()),
        None => None,
    }) { Some(__nikaia_value) => __nikaia_value, None => return Err(nikaia_std::error::throwing(ModulesRefusal::Parse, &"modules_read_unit")) };
    modules_check_imports(parsed, path, reachable, standing, host)?;
    Ok(ModulesUnit { path: nikaia_std::fs::path::clone(&(path)), source, parsed, package, renames: renames.to_owned() })
}

pub(crate) fn modules_one_namespace<H: ModulesHost>(units: &[ModulesUnit], host: &H) -> Result<(), nikaia_std::error::Thrown<ModulesRefusal>> {
    let paths: Vec<String> = units.iter().map(|unit| { nikaia_std::fs::path::display(&(unit.path)) }).collect::<Vec<_>>();
    let declared: Vec<Vec<String>> = units.iter().map(|unit| { host.declared(unit.parsed) }).collect::<Vec<_>>();
    let message = match declared_once(&paths, &declared) { Some(__nikaia_value) => __nikaia_value, None => return Ok(()) };
    return Err(nikaia_std::error::throwing(ModulesRefusal::Refused(message), &"modules_one_namespace"));
}

pub(crate) fn modules_check_imports<H: ModulesHost>(unit: i64, at: &std::path::Path, reachable: &collections::BTreeSet<String>, standing: ModulesStanding, host: &H) -> Result<(), nikaia_std::error::Thrown<ModulesRefusal>> {
    let alone = match standing {
        ModulesStanding::Alone => true,
        ModulesStanding::InProject => false,
    };
    let message = match host.use_refused(unit, at, reachable, alone) { Some(__nikaia_value) => __nikaia_value, None => return Ok(()) };
    return Err(nikaia_std::error::throwing(ModulesRefusal::Refused(message), &"modules_check_imports"));
}

pub fn modules_project_root(entry: &std::path::Path) -> Option<fs::Path> {
    let mut dir = match nikaia_std::fs::path::parent(&(entry)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    loop {
        if modules_is_file(&nikaia_std::fs::path::join(&(dir), std::path::Path::new(&("nikaia.toml")))) { return Some(dir); }
        dir = match nikaia_std::fs::path::parent(&(dir)) { Some(__nikaia_value) => __nikaia_value, None => return None };
    }
    None
}

pub(crate) fn modules_foreign_beside<H: ModulesHost>(entry: &std::path::Path, host: &H) -> Vec<String> {
    let root = match modules_project_root(entry) { Some(__nikaia_value) => __nikaia_value, None => return vec![] };
    host.foreign_crates(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&("nikaia.toml"))))
}

pub(crate) fn modules_is_dir(path: &std::path::Path) -> bool {
    let found = match fs::metadata(path, &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(_error) => { return false; },
    };
    found.is_dir()
}

pub(crate) fn modules_is_file(path: &std::path::Path) -> bool {
    let found = match fs::metadata(path, &fs::Root::Anywhere) {
        Ok(value) => value,
        Err(_error) => { return false; },
    };
    found.is_file()
}

pub trait ModulesLedgerHost {
    fn read_beside(&self, path: &std::path::Path) -> Option<Ledger>;
}

pub fn modules_sources_of<H: ModulesLedgerHost>(paths: &[fs::Path], texts: &[String], host: &H) -> collections::BTreeMap<String, String> {
    let mut sources: collections::BTreeMap<String, String> = collections::BTreeMap::new();
    for at in 0..paths.len() as i64 {
        let name = nikaia_std::index::or(match nikaia_std::fs::path::file_name(&(*nikaia_std::index::get(&paths, (at) as usize))).as_ref() {
            Some(__nikaia_it) => Some(nikaia_std::fs::path::text_of(&(__nikaia_it))),
            None => None,
        }, || nikaia_std::fs::path::text_of(&(*nikaia_std::index::get(&paths, (at) as usize))).into());
        let bytes: Vec<u8> = (*nikaia_std::index::get(&texts, (at) as usize)).bytes().collect::<Vec<_>>();
        sources.insert(name, hash::sha256_hex(&bytes));
    }
    sources
}

pub fn modules_believed<H: ModulesLedgerHost>(dependency: &ProjectMembersDependency, sources: &collections::BTreeMap<String, String>, host: &H) -> Option<Ledger> {
    let shipped = match modules_shipped_ledger(&dependency.root, host) { Some(__nikaia_value) => __nikaia_value, None => return None };
    if !stale_units(&shipped, sources).is_empty() { return None; }
    Some(published_entries(&shipped, &dependency.reachable))
}

pub(crate) fn modules_shipped_ledger<H: ModulesLedgerHost>(root: &std::path::Path, host: &H) -> Option<Ledger> { host.read_beside(&nikaia_std::fs::path::join(&(root), std::path::Path::new(&("nikaia.contracts")))) }

pub trait ModulesProgramHost {
    fn empty_ledger(&self) -> Ledger;
    fn std_library(&self) -> Ledger;
    fn package_ledger(&self, from: i64, to: i64) -> Ledger;
    fn own_ledger(&self, from: i64, to: i64, library: &Ledger) -> Ledger;
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModulesProgramParts {
    pub contracts: Ledger,
    pub as_its_own: collections::BTreeMap<String, Ledger>,
    pub own_checked_from: Option<i64>,
}

pub fn modules_program_of<H: ModulesProgramHost>(host: &H, described: &Ledger, packages: &[Option<String>], renames: &[collections::BTreeMap<String, String>], reaches: &collections::BTreeMap<String, collections::BTreeSet<String>>, their_renames: &collections::BTreeMap<String, collections::BTreeMap<String, String>>) -> ModulesProgramParts {
    let mut contracts = host.empty_ledger();
    let mut library = host.std_library();
    let as_its_own = dependency_ledgers(&mut library, &mut contracts, described, packages, renames, reaches, their_renames, &|from, to| { host.package_ledger(from, to) });
    let std_alone = described.functions.is_empty() && described.types.is_empty() && as_its_own.is_empty();
    let own_units = packages.iter().filter(|p| { p.is_none() }).count() as i64;
    let mut own_checked_from: Option<i64> = None;
    let mut own_groups = 0;
    for (from, to) in groups(packages) {
        if (*nikaia_std::index::get(&packages, nikaia_std::index::at(from))).is_some() { continue; }
        own_groups += 1;
        let own = host.own_ledger(from, to, &library);
        own_checked_from = None;
        if std_alone && to - from == own_units { own_checked_from = Some(from); }
        absorb_own(&mut contracts, nikaia_std::index::get(&renames, nikaia_std::index::at(from)), &own);
    }
    if own_groups != 1 { own_checked_from = None; }
    ModulesProgramParts { contracts, as_its_own, own_checked_from }
}

pub trait ModulesEmitHost {
    fn trust(&self) -> Provenance;
    fn keyed_functions(&self, package: &str) -> Vec<String>;
    fn own_names(&self) -> collections::BTreeSet<String>;
    fn barrier_names(&self, all: bool) -> collections::BTreeSet<String>;
    fn preamble(&self) -> String;
    fn emit_unit(&self, at: i64, provenance: Provenance, offset: i64) -> Result<String, Box<dyn std::error::Error>>;
    fn has_main(&self) -> bool;
    fn map_rows(&self) -> Vec<(i64, i64, i64)>;
}

pub fn modules_emit_reading<H: ModulesEmitHost>(host: &H, packages: &[Option<String>], shown: &[String], sources: &[&str]) -> Result<String, Box<dyn std::error::Error>> {
    let mut provenance = host.trust();
    if provenance == Provenance::Trusted {
        let called = host.own_names();
        let mut names: collections::BTreeSet<String> = collections::BTreeSet::new();
        for package in packages.iter() {
            let name = match match package.as_ref() {
                Some(__nikaia_it) => Some(__nikaia_it.clone()),
                None => None,
            } { Some(__nikaia_value) => __nikaia_value, None => continue };
            names.insert(name);
        }
        for name in names.iter() {
            let keyed = host.keyed_functions(name);
            if keyed.iter().any(|key| { called.contains(&nikaia_std::index::or(key.rsplit("::").next(), || std::convert::AsRef::<str>::as_ref(key)).to_string()) }) {
                provenance = Provenance::Untrusted;
                break;
            }
        }
    }
    if provenance == Provenance::Trusted && !host.barrier_names(false).is_empty() { provenance = Provenance::Untrusted; }
    if provenance == Provenance::Trusted {
        let barriers = host.barrier_names(true);
        if !barriers.is_empty() {
            for name in host.own_names() {
                if barriers.contains(&name) {
                    provenance = Provenance::Untrusted;
                    break;
                }
            }
        }
    }
    let mut rust: String = String::from("// Generated by the Nikaia bootstrap compiler (Stage 0).\n// Edit the .nika source, not this file.\n\n");
    rust.push_str(&host.preamble());
    rust.push_str("\n");
    for at in 0..packages.len() as i64 {
        if (*nikaia_std::index::get(&packages, nikaia_std::index::at(at))).is_some() { continue; }
        let body = host.emit_unit(at, provenance, rust.len() as i64)?;
        rust.push_str(&body);
        rust.push_str("\n");
    }
    if host.has_main() {
        let table = emit_needs_abort_table(&rust, &host.map_rows(), shown, sources);
        rust.push_str(&table);
    }
    Ok(rust)
}

